/**
 * Anti-bot block handling: one classifier for challenge and block pages, the recovery each kind
 * calls for, and the public routes to the same information when a site refuses automation.
 *
 * The signatures are data, so the page-context detector (generated by {@link challengeDetectSource})
 * and the Web proxy's server-side probe ({@link classifyBlock} on raw HTML) cannot drift apart.
 * Nothing here solves a CAPTCHA or evades a block: interactive checks go to the human, network
 * (IP) blocks are reported as an environment limit, and the rest get one paced retry and then
 * other public sources.
 * @module dsh-browser/browser/anti-bot
 */

import type { BrowserChallenge } from './types.ts'

/** What the agent should do about a blocked page. */
export type BlockRecovery =
  /** A human verification (CAPTCHA, slider, press-and-hold): hand the tab to the human. */
  | 'takeover'
  /** A self-clearing JavaScript interstitial: wait for it in the same tab, then re-check. */
  | 'wait'
  /** A refusal that a fresh session and slower pacing may get past once; then fall back. */
  | 'retry'
  /** The network itself is refused (datacenter/VPN IP): an environment limit, use other sources. */
  | 'environment'

/** Facts about a loaded page, as the classifier sees them. */
export interface BlockEvidence {
  /** HTTP status of the main document, when known. */
  readonly status?: number
  readonly title?: string
  /** Visible text (or raw HTML on the server side). */
  readonly text?: string
  /** Space-separated `src` of the page's iframes. */
  readonly frames?: string
  /** Visible challenge widgets found in the DOM, by kind (page context only). */
  readonly widgets?: readonly string[]
}

interface Signature {
  readonly kind: string
  readonly recovery: BlockRecovery
  readonly reason: string
  /** Matched against the lower-cased title + text. */
  readonly text?: string
  /** Matched against the lower-cased iframe sources. */
  readonly frames?: string
  /** A visible widget of this kind (page context). */
  readonly widget?: string
  /** Only counts on an error status (>= 400), so a page that merely mentions the words is not a block. */
  readonly errorOnly?: boolean
}

/**
 * Ordered: the first match wins, so interactive checks come before the interstitials that host
 * them and network blocks come before generic refusals.
 */
const SIGNATURES: readonly Signature[] = [
  { kind: 'hcaptcha', recovery: 'takeover', reason: 'hCaptcha verification', widget: 'hcaptcha', frames: 'hcaptcha\\.com/captcha' },
  { kind: 'recaptcha', recovery: 'takeover', reason: 'Google reCAPTCHA verification', widget: 'recaptcha', frames: 'recaptcha/(?:api2|enterprise)/bframe' },
  { kind: 'turnstile', recovery: 'takeover', reason: 'Cloudflare Turnstile verification', widget: 'turnstile', frames: 'challenges\\.cloudflare\\.com/cdn-cgi/challenge-platform/.*turnstile' },
  { kind: 'perimeterx', recovery: 'takeover', reason: 'PerimeterX "Press & Hold" verification', text: 'press (?:&|and) hold|px-captcha', widget: 'perimeterx' },
  { kind: 'datadome', recovery: 'takeover', reason: 'DataDome verification', frames: 'captcha-delivery\\.com|geo\\.captcha-delivery' },
  { kind: 'slider', recovery: 'takeover', reason: 'Slider / puzzle verification', text: '\u6ed1\u52a8|\u62d6\u52a8.{0,12}(?:\u6ed1\u5757|\u5b8c\u6210)|slide to verify|drag the slider|geetest', widget: 'slider' },
  { kind: 'google-sorry', recovery: 'environment', reason: 'Google "unusual traffic from your computer network" block', text: 'unusual traffic from your computer network|our systems have detected unusual traffic' },
  { kind: 'ip-block', recovery: 'environment', reason: 'The site refuses this network (IP / hosting provider block)', text: 'your ip(?: address)? (?:has been|is|was) (?:blocked|banned|blacklisted)|requests from your (?:ip|network) |datacenter|data center ip|hosting provider|vpn or proxy', errorOnly: true },
  { kind: 'cloudflare', recovery: 'wait', reason: 'Cloudflare "Just a moment" interstitial', widget: 'cloudflare', text: 'just a moment\\.\\.\\.|checking your browser|checking if the site connection is secure|cf-browser-verification|cf_chl_|cf-chl-' },
  { kind: 'baidu-verify', recovery: 'takeover', reason: 'Baidu security verification (\u767e\u5ea6\u5b89\u5168\u9a8c\u8bc1)', text: 'wappass\\.baidu\\.com|\u767e\u5ea6\u5b89\u5168\u9a8c\u8bc1' },
  { kind: 'human-check', recovery: 'takeover', reason: 'Human-verification challenge', text: 'verify you are (?:a )?human|verify you are not a robot|are you a robot|\u4eba\u673a\u9a8c\u8bc1|\u5b89\u5168\u9a8c\u8bc1|\u8bf7\u5b8c\u6210\u9a8c\u8bc1' },
  { kind: 'rate-limit', recovery: 'retry', reason: 'Rate limited (HTTP 429)', text: '', errorOnly: true },
  { kind: 'access-denied', recovery: 'retry', reason: 'Access denied by the site\'s bot protection', text: 'access denied|attention required|request blocked|you have been blocked|forbidden|not authorized to access|bot detected|automated (?:access|requests|queries)|enable javascript and cookies|pardon our interruption|\u8bbf\u95ee\u88ab\u62d2\u7edd|\u8bbf\u95ee\u53d7\u9650', errorOnly: true },
]

/** Signatures as JSON-safe data for the page-context detector. */
const SIGNATURE_DATA = SIGNATURES.map(s => ({ ...s }))

/**
 * Classify a page. The same function runs in the page (through {@link challengeDetectSource}) and
 * in Node, so it must stay self-contained: no imports, no closures over module state.
 * @param evidence - what the page shows.
 * @param signatures - the signature table.
 * @returns the challenge verdict.
 */
function classify(evidence: BlockEvidence, signatures: readonly Signature[]): BrowserChallenge {
  const status = typeof evidence.status === 'number' ? evidence.status : 0
  const text = ((evidence.title ?? '') + '\n' + (evidence.text ?? '')).toLowerCase()
  const frames = (evidence.frames ?? '').toLowerCase()
  const widgets = evidence.widgets ?? []
  for (const s of signatures) {
    if (s.errorOnly === true && status < 400) continue
    if (s.kind === 'rate-limit') {
      if (status === 429) return { blocked: true, kind: s.kind, reason: s.reason, recovery: s.recovery, ...status > 0 ? { status } : {} }
      continue
    }
    const hit = (s.widget !== undefined && widgets.includes(s.widget))
      || (s.frames !== undefined && new RegExp(s.frames, 'i').test(frames))
      || (s.text !== undefined && s.text !== '' && new RegExp(s.text, 'i').test(text))
    if (hit) return { blocked: true, kind: s.kind, reason: s.reason, recovery: s.recovery, ...status > 0 ? { status } : {} }
  }
  // An error page with almost nothing on it, served to a browser, is a refusal in all but name.
  if ((status === 403 || status === 503) && text.replace(/\s+/g, ' ').trim().length < 400) {
    return { blocked: true, kind: 'access-denied', reason: `HTTP ${status} with an empty page (likely a bot block)`, recovery: 'retry', status }
  }
  return { blocked: false }
}

/**
 * Classify a page from what it shows.
 * @param evidence - status, title, text, iframe sources and visible widgets.
 * @returns `{ blocked: false }` or the kind, reason and recovery.
 */
export function classifyBlock(evidence: BlockEvidence): BrowserChallenge {
  return classify(evidence, SIGNATURES)
}

/**
 * The page-context detector: collects the evidence (main-document status, visible text including
 * open shadow roots and same-origin frames, iframe sources, and challenge widgets that are actually
 * visible, so an invisible reCAPTCHA v3 badge on a login page is not a block) and classifies it.
 * @returns a JavaScript expression evaluating to a {@link BrowserChallenge}.
 */
export function challengeDetectSource(): string {
  return `(() => {
  try {
    const visible = el => { if (!el) return false; const r = el.getBoundingClientRect(); if (r.width < 30 || r.height < 30) return false; const cs = getComputedStyle(el); return cs.visibility !== 'hidden' && cs.display !== 'none' && Number(cs.opacity) > 0.05 }
    let extra = ''
    const frames = []
    const widgets = new Set()
    const seen = new Set()
    const scan = doc => {
      if (seen.has(doc)) return
      seen.add(doc)
      for (const el of doc.querySelectorAll('*')) {
        if (el.shadowRoot) { extra += '\\n' + (el.shadowRoot.textContent || '').slice(0, 2000); scan(el.shadowRoot) }
        if (el.tagName === 'IFRAME') {
          const src = el.src || ''
          frames.push(src)
          if (visible(el)) {
            if (/hcaptcha\\.com/i.test(src)) widgets.add('hcaptcha')
            if (/recaptcha\\/(?:api2|enterprise)\\/(?:anchor|bframe)/i.test(src)) widgets.add('recaptcha')
            if (/challenges\\.cloudflare\\.com/i.test(src)) widgets.add('turnstile')
          }
          try { const d = el.contentDocument; if (d) { extra += '\\n' + ((d.body && d.body.innerText) || '').slice(0, 2000); scan(d) } } catch { /* cross-origin */ }
        }
      }
    }
    scan(document)
    for (const [selector, kind] of [['.h-captcha', 'hcaptcha'], ['.g-recaptcha', 'recaptcha'], ['.cf-turnstile', 'turnstile'], ['#px-captcha', 'perimeterx'], ['.geetest_panel, .geetest_slider, .nc_wrapper, .captcha-slider, #slider-captcha', 'slider']]) {
      for (const el of document.querySelectorAll(selector)) if (visible(el)) widgets.add(kind)
    }
    if (document.querySelector('#challenge-running, #challenge-stage, #cf-chl-container, #cf-challenge-running')) widgets.add('cloudflare')
    const nav = performance.getEntriesByType && performance.getEntriesByType('navigation')[0]
    const status = nav && typeof nav.responseStatus === 'number' ? nav.responseStatus : 0
    const evidence = { status, title: document.title || '', text: ((document.body && document.body.innerText) || '').slice(0, 4000) + extra.slice(0, 4000), frames: frames.join(' '), widgets: [...widgets] }
    return (${classify.toString()})(evidence, ${JSON.stringify(SIGNATURE_DATA)})
  } catch { return { blocked: false } }
})()`
}

/**
 * How long to pause before the one retry a refused page gets, so the retry reads as a person
 * coming back rather than a script hammering. `DSH_BROWSER_BLOCK_RETRY_MS` tunes it (tests use 0).
 * @returns the pause in milliseconds.
 */
export function blockRetryDelayMs(): number {
  const raw = Number(process.env.DSH_BROWSER_BLOCK_RETRY_MS)
  return Number.isFinite(raw) && raw >= 0 ? Math.min(raw, 60_000) : 2500
}

/** One alternative public route to the information a blocked page holds. */
export interface FallbackRoute {
  readonly kind: 'api' | 'search' | 'archive'
  readonly url: string
  readonly note: string
}

const enc = encodeURIComponent

/**
 * Public, documented endpoints of well-known sites that serve the same content without a browser.
 * @param url - the blocked page.
 * @returns the site's own API routes, most specific first.
 */
function siteApis(url: URL): FallbackRoute[] {
  const host = url.hostname.replace(/^(?:www|m|old|new)\./u, '')
  const parts = url.pathname.split('/').filter(Boolean)
  const out: FallbackRoute[] = []
  if (host === 'reddit.com') {
    out.push({ kind: 'api', url: `https://www.reddit.com${url.pathname.replace(/\/$/u, '')}.json${url.search}`, note: 'Reddit JSON view of the same listing or thread' })
  } else if (host === 'github.com' && parts.length >= 2) {
    const [owner, repo, section, ...rest] = parts
    const base = `https://api.github.com/repos/${owner}/${repo}`
    const tail = section === 'issues' || section === 'pull' ? `/${section === 'pull' ? 'pulls' : 'issues'}${rest[0] !== undefined ? `/${rest[0]}` : ''}` : section === 'releases' ? '/releases' : ''
    out.push({ kind: 'api', url: base + tail, note: 'GitHub REST API' })
  } else if (/(?:^|\.)wikipedia\.org$/u.test(host) && parts[0] === 'wiki' && parts[1] !== undefined) {
    out.push({ kind: 'api', url: `https://${url.hostname}/api/rest_v1/page/html/${parts.slice(1).join('/')}`, note: 'Wikipedia REST API (page HTML)' })
  } else if (host === 'news.ycombinator.com' && url.searchParams.get('id') !== null) {
    out.push({ kind: 'api', url: `https://hacker-news.firebaseio.com/v0/item/${enc(url.searchParams.get('id')!)}.json`, note: 'Hacker News Firebase API' })
  } else if (host === 'stackoverflow.com' && parts[0] === 'questions' && parts[1] !== undefined) {
    out.push({ kind: 'api', url: `https://api.stackexchange.com/2.3/questions/${parts[1]}?site=stackoverflow&filter=withbody`, note: 'Stack Exchange API' })
  } else if (host === 'npmjs.com' && parts[0] === 'package' && parts[1] !== undefined) {
    out.push({ kind: 'api', url: `https://registry.npmjs.org/${parts.slice(1).join('/')}`, note: 'npm registry metadata' })
  } else if (host === 'pypi.org' && parts[0] === 'project' && parts[1] !== undefined) {
    out.push({ kind: 'api', url: `https://pypi.org/pypi/${parts[1]}/json`, note: 'PyPI JSON API' })
  } else if ((host === 'youtube.com' && url.searchParams.get('v') !== null) || host === 'youtu.be') {
    out.push({ kind: 'api', url: `https://www.youtube.com/oembed?format=json&url=${enc(url.href)}`, note: 'YouTube oEmbed (title, channel)' })
  }
  return out
}

/**
 * Other public routes to a blocked page's information, in the order worth trying: the site's own
 * API, search-engine results (snippets and other copies), then web archives.
 * @param target - the blocked page's URL.
 * @returns the routes; empty for a non-HTTP URL.
 */
export function fallbackRoutes(target: string): FallbackRoute[] {
  let url: URL
  try { url = new URL(target) } catch { return [] }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return []
  const bare = url.href.replace(/^https?:\/\//u, '')
  const terms = `${url.hostname} ${decodeURIComponent(url.pathname).replace(/[/_-]+/gu, ' ').trim()}`.trim()
  return [
    ...siteApis(url),
    { kind: 'search', url: `https://www.bing.com/search?q=${enc(terms)}`, note: 'Bing results: snippets and other copies of the page' },
    { kind: 'search', url: `https://duckduckgo.com/html/?q=${enc(terms)}`, note: 'DuckDuckGo HTML results' },
    { kind: 'archive', url: `https://web.archive.org/web/2/${url.href}`, note: 'Wayback Machine: latest archived copy' },
    { kind: 'archive', url: `https://archive.ph/newest/${bare}`, note: 'archive.today: latest snapshot' },
  ]
}

/**
 * What the agent is told to do for a verdict: one line, static per kind so it stays cache friendly.
 * @param challenge - the verdict.
 * @returns the instruction, or '' when the page is not blocked.
 */
export function recoveryAdvice(challenge: BrowserChallenge): string {
  if (challenge.blocked !== true) return ''
  switch (challenge.recovery) {
    case 'takeover': return 'Human verification: never solve it or retry it yourself. Call dsh_browser_request_takeover so the human completes it in the browser, then re-read the page. If takeover is skipped or unavailable, use the fallback routes.'
    case 'wait': return 'A self-clearing interstitial: dsh_browser_wait (a few seconds) and re-check; if it turns into a human check, request takeover; if it persists, use the fallback routes.'
    case 'environment': return 'The site refuses this network (an environment limit, not something to work around): do not retry. Use the fallback routes and report the block.'
    default: return 'The site refused automated access. One paced retry in a fresh session was already made when it says so; do not hammer the site. Use the fallback routes for the same public information.'
  }
}
